using System;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using AltaSoft.Storm.Attributes;
using AltaSoft.Storm.Crud;
using AltaSoft.Storm.Exceptions;
using AltaSoft.Storm.Interfaces;
using AltaSoft.Storm.TestModels;
using FluentAssertions;
using Microsoft.Data.SqlClient;
using Xunit;
using Xunit.Abstractions;

namespace AltaSoft.Storm.Tests;

/// <summary>
/// Regression tests for SQL generated by StormControllerBase:
/// single-entity concurrency check, atomicity of multi-statement batches, ORDER BY in value queries
/// and update-then-insert merge on entities without updatable columns.
/// </summary>
public class ControllerSqlFixTests : IClassFixture<DatabaseFixture>, IAsyncLifetime
{
    private readonly string _connectionString;
    private readonly TestStormContext _context;

    public ControllerSqlFixTests(DatabaseFixture fixture, ITestOutputHelper output)
    {
        StormManager.SetLogger(new XunitLogger<DatabaseFixture>(output));
        _connectionString = fixture.ConnectionString;
        _context = new TestStormContext(fixture.ConnectionString);
    }

    public async Task InitializeAsync()
    {
        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync();
        await ExecuteAsync(connection, "IF OBJECT_ID('[dbo].[LinkPk]') IS NULL CREATE TABLE [dbo].[LinkPk] ([A] int NOT NULL, [B] int NOT NULL, CONSTRAINT [PK_LinkPk] PRIMARY KEY ([A], [B]))");
    }

    public async Task DisposeAsync()
    {
        await _context.DisposeAsync();
    }

    #region 1. Single-entity UPDATE concurrency check

    [Fact]
    public async Task UpdateSingle_WithConcurrencyCheck_StaleEntity_ThrowsConcurrencyException_AndDoesNotOverwrite()
    {
        const int userId = 7001;
        await _context.InsertIntoUsersTable().Values(DatabaseHelper.NewUser(userId)).GoAsync();

        var a = await _context.SelectFromUsersTable(userId, 7).WithTracking().GetAsync();
        var b = await _context.SelectFromUsersTable(userId, 7).WithTracking().GetAsync();
        a.Should().NotBeNull();
        b.Should().NotBeNull();

        a!.LoginName = "WrittenByA";
        (await _context.UpdateUsersTable().WithConcurrencyCheck().Set(a).GoAsync()).Should().Be(1);

        b!.LoginName = "WrittenByB";
        var act = async () => await _context.UpdateUsersTable().WithConcurrencyCheck().Set(b).GoAsync();
        await act.Should().ThrowAsync<StormDbConcurrencyException>();

        var reloaded = await _context.SelectFromUsersTable(userId, 7).GetAsync();
        reloaded!.LoginName.Should().Be("WrittenByA");
    }

    [Fact]
    public async Task UpdateSingle_WithConcurrencyCheck_InsideTransactionScope_DoesNotKillCallerTransaction()
    {
        const int userId = 7002;
        const int otherUserId = 7003;
        await _context.InsertIntoUsersTable().Values(DatabaseHelper.NewUser(userId)).GoAsync();

        var a = await _context.SelectFromUsersTable(userId, 7).WithTracking().GetAsync();
        var b = await _context.SelectFromUsersTable(userId, 7).WithTracking().GetAsync();
        a!.LoginName = "WrittenByA";
        (await _context.UpdateUsersTable().WithConcurrencyCheck().Set(a).GoAsync()).Should().Be(1);

        using (var scope = new StormTransactionScope())
        {
            await using var ctx = new TestStormContext(_connectionString);

            b!.LoginName = "WrittenByB";
            var act = async () => await ctx.UpdateUsersTable().WithConcurrencyCheck().Set(b).GoAsync();
            await act.Should().ThrowAsync<StormDbConcurrencyException>();

            // The caller's transaction must still be usable after the concurrency error
            await ctx.InsertIntoUsersTable().Values(DatabaseHelper.NewUser(otherUserId)).GoAsync();

            await scope.CompleteAsync(CancellationToken.None);
        }

        (await _context.SelectFromUsersTable(otherUserId, 7).GetAsync()).Should().NotBeNull();
        (await _context.SelectFromUsersTable(userId, 7).GetAsync())!.LoginName.Should().Be("WrittenByA");
    }

    [Fact]
    public async Task Merge_WithConcurrencyCheck_StaleEntity_ThrowsConcurrencyException_AndDoesNotOverwrite()
    {
        const int userId = 7008;
        await _context.InsertIntoUsersTable().Values(DatabaseHelper.NewUser(userId)).GoAsync();

        var a = await _context.SelectFromUsersTable(userId, 7).WithTracking().GetAsync();
        var b = await _context.SelectFromUsersTable(userId, 7).WithTracking().GetAsync();
        a!.LoginName = "WrittenByA";
        (await _context.UpdateUsersTable().WithConcurrencyCheck().Set(a).GoAsync()).Should().Be(1);

        b!.LoginName = "WrittenByB";

        var updateThenInsert = async () => await _context.MergeIntoUsersTable().WithConcurrencyCheck().UpdateOrInsert(b).GoAsync();
        await updateThenInsert.Should().ThrowAsync<StormDbConcurrencyException>();

        var insertThenUpdate = async () => await _context.MergeIntoUsersTable().WithConcurrencyCheck().InsertOrUpdate(b).GoAsync();
        await insertThenUpdate.Should().ThrowAsync<StormDbConcurrencyException>();

        (await _context.SelectFromUsersTable(userId, 7).GetAsync())!.LoginName.Should().Be("WrittenByA");
    }

    [Fact]
    public async Task UpdateSingle_WithConcurrencyCheck_MissingRow_ReturnsZeroWithoutException()
    {
        var ghost = DatabaseHelper.NewUser(7099);

        var result = await _context.UpdateUsersTable().WithConcurrencyCheck().Set(ghost).GoAsync();

        result.Should().Be(0);
    }

    [Fact]
    public async Task UpdateList_WithConcurrencyCheck_StaleEntity_ThrowsConcurrencyException_AndRollsBackWholeBatch()
    {
        const int userId1 = 7004;
        const int userId2 = 7005;
        await _context.InsertIntoUsersTable().Values([DatabaseHelper.NewUser(userId1), DatabaseHelper.NewUser(userId2)]).GoAsync();

        var fresh = await _context.SelectFromUsersTable(userId1, 7).WithTracking().GetAsync();
        var a = await _context.SelectFromUsersTable(userId2, 7).WithTracking().GetAsync();
        var stale = await _context.SelectFromUsersTable(userId2, 7).WithTracking().GetAsync();

        a!.LoginName = "WrittenByA";
        (await _context.UpdateUsersTable().WithConcurrencyCheck().Set(a).GoAsync()).Should().Be(1);

        fresh!.LoginName = "BatchFresh";
        stale!.LoginName = "BatchStale";
        var act = async () => await _context.UpdateUsersTable().WithConcurrencyCheck().Set([fresh, stale]).GoAsync();
        await act.Should().ThrowAsync<StormDbConcurrencyException>();

        (await _context.SelectFromUsersTable(userId1, 7).GetAsync())!.LoginName.Should().NotBe("BatchFresh");
        (await _context.SelectFromUsersTable(userId2, 7).GetAsync())!.LoginName.Should().Be("WrittenByA");
    }

    [Fact]
    public async Task UpdateList_WithConcurrencyCheck_FreshEntities_Succeeds()
    {
        const int userId1 = 7006;
        const int userId2 = 7007;
        await _context.InsertIntoUsersTable().Values([DatabaseHelper.NewUser(userId1), DatabaseHelper.NewUser(userId2)]).GoAsync();

        var u1 = await _context.SelectFromUsersTable(userId1, 7).WithTracking().GetAsync();
        var u2 = await _context.SelectFromUsersTable(userId2, 7).WithTracking().GetAsync();
        u1!.LoginName = "L1";
        u2!.LoginName = "L2";

        var result = await _context.UpdateUsersTable().WithConcurrencyCheck().Set([u1, u2]).GoAsync();

        result.Should().Be(2);
        (await _context.SelectFromUsersTable(userId1, 7).GetAsync())!.LoginName.Should().Be("L1");
        (await _context.SelectFromUsersTable(userId2, 7).GetAsync())!.LoginName.Should().Be("L2");
    }

    #endregion

    #region 2. Atomic multi-statement batches

    [Fact]
    public async Task InsertList_WithPrimaryKeyViolation_ThrowsAndCommitsNothing()
    {
        await _context.InsertIntoUsersTable().Values(DatabaseHelper.NewUser(7020)).GoAsync();

        var act = async () => await _context.InsertIntoUsersTable().Values([DatabaseHelper.NewUser(7021), DatabaseHelper.NewUser(7020)]).GoAsync();
        await act.Should().ThrowAsync<StormPrimaryKeyViolationException>();

        (await _context.SelectFromUsersTable(7021, 7).GetAsync()).Should().BeNull();
    }

    [Fact]
    public async Task MergeList_InsertThenUpdate_StillUpdatesExistingRows()
    {
        // Insert-then-update merge catches PK violations inside the batch; this must keep working inside the atomic wrapper.
        await _context.InsertIntoUsersTable().Values(DatabaseHelper.NewUser(7030)).GoAsync();

        var existing = DatabaseHelper.NewUser(7030);
        existing.LoginName = "Merged7030";
        var newOne = DatabaseHelper.NewUser(7031);
        newOne.LoginName = "Merged7031";

        await _context.MergeIntoUsersTable().WithoutConcurrencyCheck().InsertOrUpdate([existing, newOne]).GoAsync();

        (await _context.SelectFromUsersTable(7030, 7).GetAsync())!.LoginName.Should().Be("Merged7030");
        (await _context.SelectFromUsersTable(7031, 7).GetAsync())!.LoginName.Should().Be("Merged7031");
    }

    #endregion

    #region 3. ORDER BY in value queries

    [Fact]
    public async Task ValueQuery_OrderByColumnAfterDetailTables_UsesCorrectColumn()
    {
        const int userId = 7040;
        var user = DatabaseHelper.NewUser(userId);
        user.LoginName = "Blocked7040";
        user.UserStatus = UserStatus.Blocked;
        await _context.InsertIntoUsersTable().Values(user).GoAsync();

        var list = await _context.SelectFromUsersTable().OrderBy(User.OrderBy.UserStatus).ListAsync(x => x.LoginName);
        list.Should().NotBeEmpty();
        list.Last().Should().Be("Blocked7040");

        var first = await _context.SelectFromUsersTable().OrderBy(User.OrderBy.UserStatus_Desc).GetAsync(x => x.LoginName);
        first.HasValue.Should().BeTrue();
        first.Value.Should().Be("Blocked7040");

        var tuples = await _context.SelectFromUsersTable().OrderBy(User.OrderBy.NullableUserStatus_Desc, User.OrderBy.UserStatus_Desc).ListAsync(x => x.LoginName, x => x.UserStatus);
        tuples.Should().NotBeEmpty();
    }

    #endregion

    #region 4. Merge (update-then-insert) on an entity without updatable columns

    [Fact]
    public async Task MergeUpdateThenInsert_AllPkEntity_ExistingRow_DoesNotThrow()
    {
        var ctrl = new LinkPkController();
        var value = new LinkPk { A = 1, B = 2 };

        (await ctrl.MergeAsync(value, false, true, new MergeInto<LinkPk>(_context, 0))).Should().BeGreaterThanOrEqualTo(0);
        // Row exists now: update-then-insert must not try to insert it again
        var act = async () => await ctrl.MergeAsync(value, false, true, new MergeInto<LinkPk>(_context, 0));
        await act.Should().NotThrowAsync();

        // Insert-then-update must work as well
        var act2 = async () => await ctrl.MergeAsync(value, false, false, new MergeInto<LinkPk>(_context, 0));
        await act2.Should().NotThrowAsync();

        // Multi-row variant
        var act3 = async () => await ctrl.MergeAsync([value, new LinkPk { A = 1, B = 3 }], false, true, new MergeInto<LinkPk>(_context, 0));
        await act3.Should().NotThrowAsync();

        await using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync();
        await using var cmd = connection.CreateCommand();
        cmd.CommandText = "SELECT COUNT(*) FROM [dbo].[LinkPk] WHERE [A] = 1";
        ((int)(await cmd.ExecuteScalarAsync())!).Should().Be(2);
    }

    /// <summary>
    /// Hand-written link entity (all columns are part of the primary key). The source generator does not run on the test project.
    /// </summary>
    internal sealed class LinkPk : IDataBindable
    {
        public int A { get; set; }
        public int B { get; set; }

        public uint? __GetLoadingFlags() => null;

        public (StormColumnDef column, object? value)[] __GetColumnValues() =>
        [
            (LinkPkController.ColumnDefsStatic[0], A),
            (LinkPkController.ColumnDefsStatic[1], B)
        ];

        public void __AddDetailRow(StormColumnDef column, object row) => throw new NotSupportedException();

        public void __SetAutoIncValue(SqlDataReader dr, int idx) => throw new NotSupportedException();
    }

    internal sealed class LinkPkController : StormControllerBase
    {
        internal static readonly StormColumnDef[] ColumnDefsStatic =
        [
            new(nameof(LinkPk.A), null, "A", StormColumnFlags.Key | StormColumnFlags.CanSelect | StormColumnFlags.CanInsert, UnifiedDbType.Int32, 0, 0, 0, SaveAs.Default, 0, false, null, null, typeof(int), null),
            new(nameof(LinkPk.B), null, "B", StormColumnFlags.Key | StormColumnFlags.CanSelect | StormColumnFlags.CanInsert, UnifiedDbType.Int32, 0, 0, 0, SaveAs.Default, 0, false, null, null, typeof(int), null)
        ];

        private static readonly StormColumnDef[][] s_keyColumnDefs = [[ColumnDefsStatic[0], ColumnDefsStatic[1]]];

        public LinkPkController() : base("dbo", "LinkPk", DbObjectType.Table)
        {
        }

        public override Type StormContext => typeof(TestStormContext);
        public override StormColumnDef[] ColumnDefs => ColumnDefsStatic;
        public override StormColumnDef[][] KeyColumnDefs => s_keyColumnDefs;
        public override bool HasConcurrencyCheck => false;
        public override uint PartialLoadFlagsAll => 0;
        public override uint PartialLoadFlagsAllWithoutDetails => 0;
        public override StormColumnDef? __GetAutoIncColumn() => null;

        public override IDataBindable Create(SqlDataReader dr, uint partialLoadFlags, ref int idx) =>
            new LinkPk { A = dr.GetInt32(idx++), B = dr.GetInt32(idx++) };

        public override object? ReadSingleScalarValue(SqlDataReader dr, string propertyName, ref int idx) => dr.GetInt32(idx++);

        public override object CreateDetailRow(StormColumnDef column, SqlDataReader dr, ref int idx) => throw new NotSupportedException();
    }

    #endregion

    private static async Task ExecuteAsync(SqlConnection connection, string sql)
    {
        await using var cmd = connection.CreateCommand();
        cmd.CommandText = sql;
        await cmd.ExecuteNonQueryAsync();
    }
}
